/// @brief Enumeration for the error codes of NNStreamer.
/// @since_tizen 5.5
abstract class ml_error_e {
  /// < Success!
  static const int ML_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int ML_ERROR_INVALID_PARAMETER = -22;

  /// < Cannot create or access the pipeline.
  static const int ML_ERROR_STREAMS_PIPE = -86;

  /// < The pipeline is not ready, yet (not negotiated, yet)
  static const int ML_ERROR_TRY_AGAIN = -11;

  /// < Unknown error
  static const int ML_ERROR_UNKNOWN = -1073741824;

  /// < Time out
  static const int ML_ERROR_TIMED_OUT = -1073741823;

  /// < The feature is not supported
  static const int ML_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Permission denied
  static const int ML_ERROR_PERMISSION_DENIED = -13;

  /// < Out of memory (Since 6.0)
  static const int ML_ERROR_OUT_OF_MEMORY = -12;

  /// < I/O error for database and filesystem (Since 7.0)
  static const int ML_ERROR_IO_ERROR = -5;
}

/// @brief Types of NNFWs.
/// @details To check if a nnfw-type is supported in a system, an application may call the API, ml_check_nnfw_availability().
/// @since_tizen 5.5
abstract class ml_nnfw_type_e {
  /// < NNFW is not specified (Try to determine the NNFW with file extension).
  static const int ML_NNFW_TYPE_ANY = 0;

  /// < Custom filter (Independent shared object).
  static const int ML_NNFW_TYPE_CUSTOM_FILTER = 1;

  /// < Tensorflow-lite (.tflite).
  static const int ML_NNFW_TYPE_TENSORFLOW_LITE = 2;

  /// < Tensorflow (.pb).
  static const int ML_NNFW_TYPE_TENSORFLOW = 3;

  /// < Neural Network Inference framework, which is developed by SR (Samsung Research).
  static const int ML_NNFW_TYPE_NNFW = 4;

  /// < Intel Movidius Neural Compute SDK (libmvnc). (Since 6.0)
  static const int ML_NNFW_TYPE_MVNC = 5;

  /// < Intel OpenVINO. (Since 6.0)
  static const int ML_NNFW_TYPE_OPENVINO = 6;

  /// < VeriSilicon's Vivante. (Since 6.0)
  static const int ML_NNFW_TYPE_VIVANTE = 7;

  /// < Google Coral Edge TPU (USB). (Since 6.0)
  static const int ML_NNFW_TYPE_EDGE_TPU = 8;

  /// < Arm Neural Network framework (support for caffe and tensorflow-lite). (Since 6.0)
  static const int ML_NNFW_TYPE_ARMNN = 9;

  /// < Qualcomm SNPE (Snapdragon Neural Processing Engine (.dlc). (Since 6.0)
  static const int ML_NNFW_TYPE_SNPE = 10;

  /// < PyTorch (.pt). (Since 6.5)
  static const int ML_NNFW_TYPE_PYTORCH = 11;

  /// < Inference supported from NNTrainer, SR On-device Training Framework (Since 6.5)
  static const int ML_NNFW_TYPE_NNTR_INF = 12;

  /// < Inference framework for Samsung Tizen TV (Since 6.5)
  static const int ML_NNFW_TYPE_VD_AIFW = 13;

  /// < TRIxENGINE accesses TRIV/TRIA NPU low-level drivers directly (.tvn). (Since 6.5) You may need to use high-level drivers wrapping this low-level driver in some devices: e.g., AIFW
  static const int ML_NNFW_TYPE_TRIX_ENGINE = 14;

  /// < Apache MXNet (Since 7.0)
  static const int ML_NNFW_TYPE_MXNET = 15;

  /// < Apache TVM (Since 7.0)
  static const int ML_NNFW_TYPE_TVM = 16;

  /// < Open Neural Network Exchange (ONNX) Runtime (Since 9.0)
  static const int ML_NNFW_TYPE_ONNX_RUNTIME = 17;

  /// < Tencent ncnn (Since 9.0)
  static const int ML_NNFW_TYPE_NCNN = 18;

  /// < NVidia Tensor-RT (Since 9.0)
  static const int ML_NNFW_TYPE_TENSORRT = 19;

  /// < Qualcomm QNN (Qualcomm® AI Engine Direct) (Since 9.0)
  static const int ML_NNFW_TYPE_QNN = 20;

  /// < SNAP (Samsung Neural Acceleration Platform), only for Android. (Since 6.0)
  static const int ML_NNFW_TYPE_SNAP = 8193;
}

/// @brief Types of hardware resources to be used for NNFWs. Note that if the affinity (nnn) is not supported by the driver or hardware, it is ignored.
/// @since_tizen 5.5
abstract class ml_nnfw_hw_e {
  /// < Hardware resource is not specified.
  static const int ML_NNFW_HW_ANY = 0;

  /// < Try to schedule and optimize if possible.
  static const int ML_NNFW_HW_AUTO = 1;

  /// < 0x1000: any CPU. 0x1nnn: CPU # nnn-1.
  static const int ML_NNFW_HW_CPU = 4096;

  /// < 0x1100: SIMD in CPU. (Since 6.0)
  static const int ML_NNFW_HW_CPU_SIMD = 4352;

  /// < 0x1100: NEON (alias for SIMD) in CPU. (Since 6.0)
  static const int ML_NNFW_HW_CPU_NEON = 4352;

  /// < 0x2000: any GPU. 0x2nnn: GPU # nnn-1.
  static const int ML_NNFW_HW_GPU = 8192;

  /// < 0x3000: any NPU. 0x3nnn: NPU # nnn-1.
  static const int ML_NNFW_HW_NPU = 12288;

  /// < 0x3001: Intel Movidius Stick. (Since 6.0)
  static const int ML_NNFW_HW_NPU_MOVIDIUS = 12289;

  /// < 0x3002: Google Coral Edge TPU (USB). (Since 6.0)
  static const int ML_NNFW_HW_NPU_EDGE_TPU = 12290;

  /// < 0x3003: VeriSilicon's Vivante. (Since 6.0)
  static const int ML_NNFW_HW_NPU_VIVANTE = 12291;

  /// < 0x3004: Samsung S.LSI. (Since 6.5)
  static const int ML_NNFW_HW_NPU_SLSI = 12292;

  /// < 0x13000: any SR (Samsung Research) made NPU. (Since 6.0)
  static const int ML_NNFW_HW_NPU_SR = 77824;
}

/// @brief Possible data element types of tensor in NNStreamer.
/// @since_tizen 5.5
abstract class ml_tensor_type_e {
  /// < Integer 32bit
  static const int ML_TENSOR_TYPE_INT32 = 0;

  /// < Unsigned integer 32bit
  static const int ML_TENSOR_TYPE_UINT32 = 1;

  /// < Integer 16bit
  static const int ML_TENSOR_TYPE_INT16 = 2;

  /// < Unsigned integer 16bit
  static const int ML_TENSOR_TYPE_UINT16 = 3;

  /// < Integer 8bit
  static const int ML_TENSOR_TYPE_INT8 = 4;

  /// < Unsigned integer 8bit
  static const int ML_TENSOR_TYPE_UINT8 = 5;

  /// < Float 64bit
  static const int ML_TENSOR_TYPE_FLOAT64 = 6;

  /// < Float 32bit
  static const int ML_TENSOR_TYPE_FLOAT32 = 7;

  /// < Integer 64bit
  static const int ML_TENSOR_TYPE_INT64 = 8;

  /// < Unsigned integer 64bit
  static const int ML_TENSOR_TYPE_UINT64 = 9;

  /// < FP16, IEEE 754. Note that this type is supported only in aarch64/arm devices. (Since 7.0)
  static const int ML_TENSOR_TYPE_FLOAT16 = 10;

  /// < Unknown type
  static const int ML_TENSOR_TYPE_UNKNOWN = 11;
}

